const o = {
  n: 0,
  inc() { this.n++; return this; },
  dec() { this.n--; },
  show() { return this.n; },
};
function main(): void {
  console.log(o.inc() === o, o.n);
  const r = o.inc();
  r.inc();
  console.log(o.n, r.n, o.inc().inc().n, o.n);
  o.dec(); o.dec();
  console.log(o.n, o.show());
}
